import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Ceramic grain texture background plane
  const texture = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  texture.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(1.6, 1); // Atlas aspect ratio 512:320
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Text: "Pricing 2"
  const textString = (typeof config.textContent === 'string'
    ? config.textContent
    : config.textContent?.content) || 'Pricing 2';

  const textMesh = ctx.fontAtlas.createText(textString, {
    fontSize: 0.2,
    fontWeight: 400,
    fontFamily: 'Lora',
    color: 0xe8ecf2, // paper
  });

  if (textMesh) {
    textMesh.position.y = 0.2;
    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
